import java.text.*;
import java.util.*;
public class T {
  public static void main(String[] args) throws Exception {
    for (String p : new String[]{"yyyyy-MM-dd'T'HH:mm:ss.SSS'Z'","yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}) {
      SimpleDateFormat sdf = new SimpleDateFormat(p);
      sdf.setTimeZone(TimeZone.getTimeZone("UTC"));
      sdf.setLenient(true);
      for (String s : new String[]{
        "2024-01-15T13:47:00.000Z",
        "2024-08-05T01:47:00.123Z",
        "02024-01-15T13:47:00.000Z"
      }) {
        try {
          Date d = sdf.parse(s);
          System.out.println(p + " | " + s + " -> " + d.toInstant());
        } catch (Exception e) {
          System.out.println(p + " | " + s + " -> FAIL " + e.getMessage());
        }
      }
    }
    // UUID pattern
    String pat = "^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$";
    System.out.println(java.util.UUID.randomUUID().toString().matches(pat));
  }
}
EOF
